import os,re,subprocess,collections

decls=[]  # (pkgname, pkgdir, name, recv, file, line)
for root,dirs,files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'): continue
        p=os.path.join(root,f)
        src=open(p).read()
        m=re.search(r'^package (\w+)',src,re.M)
        pkg=m.group(1) if m else '?'
        for i,line in enumerate(src.split('\n'),1):
            mm=re.match(r'^func (\(([^)]*)\) )?([A-Za-z_]\w*)\(',line)
            if mm:
                decls.append((pkg,root,mm.group(3),mm.group(2) or '',p,i))
print(len(decls),'decls')

# gather all go files repo-wide
allgo=subprocess.run(['bash','-c',"find . -name '*.go' -not -path './web/*'"],capture_output=True,text=True).stdout.split()
contents={f:open(f).read() for f in allgo}

res=[]
for pkg,pdir,name,recv,file,line in decls:
    if recv:
        # method: count .Name( repo-wide (excluding decl lines)
        pat=re.compile(r'\.'+re.escape(name)+r'\(')
    else:
        pat=None
    total=0
    tests=0
    for f,src in contents.items():
        if recv:
            n=len(pat.findall(src))
        else:
            n=len(re.findall(r'\b'+re.escape(pkg)+r'\.'+re.escape(name)+r'\(',src))
            if f.startswith(pdir+'/') or os.path.dirname(f)==pdir:
                # in-package bare calls
                n+=len(re.findall(r'(?<![\w.])'+re.escape(name)+r'\(',src))
                n-=len(re.findall(r'^func '+re.escape(name)+r'\(',src,re.M))
        if n:
            if '_test.go' in f: tests+=n
            else: total+=n
    res.append((total,tests,pkg,name,recv,file,line))

res.sort(reverse=True)
for r in res[:25]:
    print(r[0],'(tests:%d)'%r[1], r[2]+'.'+r[3], 'recv=%s'%r[4], r[5]+':'+str(r[6]))
EOF

